t.script:
(function () {
    var f = document.getElementById('wa-decide-form');
    if (!f) { return; }
    var by = null;
    f.querySelectorAll('button[name=action]').forEach(function (b) {
        b.addEventListener('click', function () { by = b.value; });
    });
    // 📎 Proof: picked files and recorded voice notes are kept in one list and
    // copied into the hidden `files` input just before a Send back is posted.
    var proof = [], MAX_FILES = 10, MAX_BYTES = 50 * 1024 * 1024;
    var pick = document.getElementById('wa-pick'), mic = document.getElementById('wa-mic'),
        hidden = document.getElementById('wa-files'), chips = document.getElementById('wa-chips'),
        perr = document.getElementById('wa-proof-err');
    function size(n) { return n < 1048576 ? Math.round(n / 1024) + ' KB' : (n / 1048576).toFixed(1) + ' MB'; }
    function say(msg) { if (perr) { perr.textContent = msg || ''; perr.style.display = msg ? 'block' : 'none'; } }
    function kind(file) {
        var t = (file.type || '').toLowerCase();
        if (t.indexOf('image/') === 0) { return '📷'; }
        if (t.indexOf('video/') === 0) { return '🎥'; }
        if (t.indexOf('audio/') === 0) { return '🎵'; }
        return '';
    }
    function add(file) {
        if (!kind(file)) { say('"' + file.name + '" is not a photo, video or audio.'); return; }
        if (file.size > MAX_BYTES) { say('"' + file.name + '" is ' + size(file.size) + '. The limit is 50 MB.'); return; }
        if (proof.length >= MAX_FILES) { say('At most ' + MAX_FILES + ' files.'); return; }
        proof.push(file);
    }
    // Photos and videos as thumbnails (tap = full screen), voice notes
    // with a player. Object URLs are freed on every redraw.
    var urls = [];
    var view = document.getElementById('wa-view');
    function open(file, url, isVideo) {
        if (!view) { return; }
        var body = view.querySelector('.body');
        body.textContent = '';
        var el = document.createElement((file ? kind(file) === '🎥' : isVideo) ? 'video' : 'img');
        el.src = url;
        if (el.tagName === 'VIDEO') { el.controls = true; el.autoplay = true; el.playsInline = true; }
        body.appendChild(el);
        view.classList.add('on');
    }
    function shut() {
        if (!view) { return; }
        var v = view.querySelector('video'); if (v) { v.pause(); }
        view.classList.remove('on'); view.querySelector('.body').textContent = '';
    }
    // 📎 The team's photos and videos: the same full-screen viewer.
    document.querySelectorAll('[data-view]').forEach(function (t) {
        t.addEventListener('click', function () {
            open(null, t.getAttribute('data-view'), t.getAttribute('data-kind') === 'video');
        });
    });
    if (view) {
        view.querySelector('.close').addEventListener('click', shut);
        view.addEventListener('click', function (e) { if (e.target === view) { shut(); } });
        document.addEventListener('keydown', function (e) { if (e.key === 'Escape') { shut(); } });
    }
    function draw() {
        if (!chips) { return; }
        urls.forEach(function (u) { URL.revokeObjectURL(u); }); urls = [];
        chips.textContent = '';
        var grid = document.createElement('div'); grid.className = 'wa-thumbs';
        proof.forEach(function (file, i) {
            var url = URL.createObjectURL(file); urls.push(url);
            var drop = function (e) { e.preventDefault(); e.stopPropagation(); proof.splice(i, 1); draw(); };
            if (kind(file) === '🎵') {
                var a = document.createElement('div'); a.className = 'wa-audio';
                var au = document.createElement('audio'); au.controls = true; au.src = url; au.preload = 'metadata';
                var nm = document.createElement('span'); nm.className = 'wa-meta'; nm.style.margin = '0';
                nm.textContent = size(file.size);
                var bx = document.createElement('button'); bx.type = 'button'; bx.textContent = '✕';
                bx.setAttribute('aria-label', 'Remove ' + file.name); bx.addEventListener('click', drop);
                a.appendChild(au); a.appendChild(nm); a.appendChild(bx); chips.appendChild(a);
                return;
            }
            var t = document.createElement('div'); t.className = 'wa-thumb';
            t.title = file.name + ' · ' + size(file.size);
            var media;
            if (kind(file) === '🎥') {
                media = document.createElement('video'); media.src = url + '#t=0.1';
                media.muted = true; media.preload = 'metadata'; media.playsInline = true;
                var pl = document.createElement('div'); pl.className = 'play'; pl.textContent = '▶';
                t.appendChild(media); t.appendChild(pl);
            } else {
                media = document.createElement('img'); media.src = url; media.alt = file.name;
                t.appendChild(media);
            }
            var cap = document.createElement('div'); cap.className = 'nm'; cap.textContent = file.name;
            var x = document.createElement('button'); x.type = 'button'; x.className = 'x'; x.textContent = '✕';
            x.setAttribute('aria-label', 'Remove ' + file.name); x.addEventListener('click', drop);
            t.appendChild(cap); t.appendChild(x);
            t.addEventListener('click', function () { open(file, url); });
            grid.appendChild(t);
        });
        if (grid.childNodes.length) { chips.insertBefore(grid, chips.firstChild); }
    }
    if (pick) {
        pick.addEventListener('change', function () {
            say('');
            Array.prototype.forEach.call(pick.files || [], add);
            pick.value = ''; draw();
        });
    }
    // 🎤 Tap to record, tap again to stop. Phones without MediaRecorder can
    // still attach a recording from their voice recorder app with 📷.
    var rec = null, chunks = [], started = 0;
    if (mic) {
        if (!(window.MediaRecorder && navigator.mediaDevices && navigator.mediaDevices.getUserMedia)) {
            mic.style.display = 'none';
        }
        mic.addEventListener('click', function () {
            if (rec && rec.state === 'recording') { rec.stop(); return; }
            say('');
            navigator.mediaDevices.getUserMedia({ audio: true }).then(function (stream) {
                chunks = []; started = Date.now();
                rec = new MediaRecorder(stream);
                rec.ondataavailable = function (e) { if (e.data && e.data.size) { chunks.push(e.data); } };
                rec.onstop = function () {
                    stream.getTracks().forEach(function (t) { t.stop(); });
                    mic.textContent = '🎤 Voice note'; mic.style.background = '#6c757d';
                    var type = rec.mimeType || 'audio/webm', secs = Math.round((Date.now() - started) / 1000);
                    var ext = type.indexOf('mp4') > -1 ? 'm4a' : (type.indexOf('ogg') > -1 ? 'ogg' : 'webm');
                    var name = 'Voice note ' + (proof.length + 1) + ' (' + Math.floor(secs / 60) + 'm' + ('0' + secs % 60).slice(-2) + 's).' + ext;
                    add(new File(chunks, name, { type: type.split(';')[0] }));
                    draw();
                };
                rec.start();
                mic.textContent = '⏹ Stop recording'; mic.style.background = '#dc3545';
            }).catch(function () { say('The microphone could not be opened. Allow it in your browser, or attach a recording with 📷.'); });
        });
    }
    f.addEventListener('submit', function (e) {
        var fb = f.querySelector('[name=feedback]');
        if ((by === 'reject' || by === 'clarify') && fb.value.trim().length < 3) {
            e.preventDefault();
            document.getElementById('wa-need-reason').style.display = 'block';
            fb.focus();
            return;
        }
        if (rec && rec.state === 'recording') {
            e.preventDefault(); say('Stop the recording first (⏹), then tap Send back.'); return;
        }
        if (hidden) {
            var dt = new DataTransfer();
            if (by === 'reject') { proof.forEach(function (file) { dt.items.add(file); }); }
            hidden.files = dt.files;
        }
        f.querySelectorAll('button[name=action]').forEach(function (b) { b.disabled = true; });
        // A disabled submit button is not posted: carry the action ourselves.
        var a = document.createElement('input'); a.type = 'hidden'; a.name = 'action'; a.value = by || '';
        f.appendChild(a);
    });
})();

(function () {
    // Signature box: Auto writes the chosen name in a handwriting
    // font, Draw signs by hand, Load takes a picture. A saved one
    // (that person's contact) is shown first.
    var cv = document.getElementById('sg-canvas');
    if (!cv) { return; }
    var ctx = cv.getContext('2d'), mode = 'auto', inked = false, drawing = false, last = null;
    var who = document.getElementById('so-signer') || document.getElementById('so-name');
    var saved = document.getElementById('sg-saved'), file = document.getElementById('sg-file');
    var tabs = document.querySelectorAll('.sg-tabs button[data-mode]');
    function clear() { ctx.clearRect(0, 0, cv.width, cv.height); inked = false; }
    function name() {
        if (!who) { return ''; }
        if (who.tagName === 'SELECT') { var o = who.options[who.selectedIndex]; return o && o.value ? o.text : ''; }
        return who.value.trim();
    }
    function auto() {
        clear();
        var n = name();
        if (!n) { return; }
        var size = 110;
        ctx.fillStyle = '#1F2937'; ctx.textBaseline = 'middle'; ctx.textAlign = 'center';
        do { ctx.font = size + 'px KpiSign, cursive'; size -= 6; } while (ctx.measureText(n).width > cv.width - 60 && size > 30);
        ctx.fillText(n, cv.width / 2, cv.height / 2);
        inked = true;
    }
    function image(src) {
        var im = new Image();
        im.onload = function () {
            clear();
            var r = Math.min((cv.width - 20) / im.width, (cv.height - 20) / im.height);
            ctx.drawImage(im, (cv.width - im.width * r) / 2, (cv.height - im.height * r) / 2, im.width * r, im.height * r);
            inked = true;
        };
        im.src = src;
    }
    function setMode(m) {
        mode = m;
        tabs.forEach(function (b) { b.classList.toggle('on', b.getAttribute('data-mode') === m); });
        saved.style.display = 'none';
        if (m === 'auto') { auto(); }
        else if (m === 'draw') { clear(); }
        else { file.click(); }
    }
    tabs.forEach(function (b) { b.addEventListener('click', function () { setMode(b.getAttribute('data-mode')); }); });
    document.getElementById('sg-clear').addEventListener('click', function () { clear(); if (mode !== 'draw') { setMode('draw'); } });
    file.addEventListener('change', function () {
        var f = file.files && file.files[0];
        if (!f) { return; }
        var rd = new FileReader(); rd.onload = function () { image(rd.result); }; rd.readAsDataURL(f);
        file.value = '';
    });
    function pickName() {
        var o = who && who.tagName === 'SELECT' ? who.options[who.selectedIndex] : null;
        var sig = o ? o.getAttribute('data-sig') : '';
        if (sig) {
            mode = 'saved'; tabs.forEach(function (b) { b.classList.remove('on'); });
            image(sig); saved.style.display = 'block';
        } else { setMode('auto'); }
    }
    if (who) { who.addEventListener(who.tagName === 'SELECT' ? 'change' : 'input', pickName); }
    function pos(e) {
        var r = cv.getBoundingClientRect(), t = e.touches ? e.touches[0] : e;
        return { x: (t.clientX - r.left) * cv.width / r.width, y: (t.clientY - r.top) * cv.height / r.height };
    }
    function down(e) { if (mode !== 'draw') { return; } e.preventDefault(); drawing = true; last = pos(e); }
    function move(e) {
        if (!drawing) { return; }
        e.preventDefault();
        var p = pos(e);
        ctx.strokeStyle = '#1F2937'; ctx.lineWidth = 4; ctx.lineCap = 'round';
        ctx.beginPath(); ctx.moveTo(last.x, last.y); ctx.lineTo(p.x, p.y); ctx.stroke();
        last = p; inked = true;
    }
    function up() { drawing = false; }
    cv.addEventListener('mousedown', down); cv.addEventListener('mousemove', move); window.addEventListener('mouseup', up);
    cv.addEventListener('touchstart', down, { passive: false }); cv.addEventListener('touchmove', move, { passive: false });
    cv.addEventListener('touchend', up);
    if (document.fonts && document.fonts.load) { document.fonts.load('40px KpiSign').then(function () { if (mode === 'auto') { auto(); } }); }
    window.soSign = {
        empty: function () { return !inked; },
        png: function () { return cv.toDataURL('image/png'); },
        need: function () {
            var b = document.getElementById('so-signbox');
            b.scrollIntoView({ behavior: 'smooth', block: 'center' });
            cv.style.borderColor = 'var(--danger)';
            setTimeout(function () { cv.style.borderColor = ''; }, 2000);
        }
    };
})();

(function () {
    var f = document.getElementById('so-form');
    if (!f) { return; }
    var by = null;
    f.querySelectorAll('button[name=action]').forEach(function (b) {
        b.addEventListener('click', function () { by = b.value; });
    });
    var proof = [], urls = [], MAX_FILES = 10, MAX_BYTES = 50 * 1024 * 1024;
    var pick = document.getElementById('so-pick'), mic = document.getElementById('so-mic'),
        hidden = document.getElementById('so-files'), chips = document.getElementById('so-chips'),
        perr = document.getElementById('so-err'), view = document.getElementById('so-view');
    function size(n) { return n < 1048576 ? Math.round(n / 1024) + ' KB' : (n / 1048576).toFixed(1) + ' MB'; }
    function say(m) { perr.textContent = m || ''; perr.style.display = m ? 'block' : 'none'; }
    function kind(file) {
        var t = (file.type || '').toLowerCase();
        return t.indexOf('image/') === 0 ? 'img' : t.indexOf('video/') === 0 ? 'vid' : t.indexOf('audio/') === 0 ? 'aud' : '';
    }
    function add(file) {
        if (!kind(file)) { say('"' + file.name + '" is not a photo, video or audio.'); return; }
        if (file.size > MAX_BYTES) { say('"' + file.name + '" is ' + size(file.size) + '. The limit is 50 MB.'); return; }
        if (proof.length >= MAX_FILES) { say('At most ' + MAX_FILES + ' files.'); return; }
        proof.push(file);
    }
    function open(file, url) {
        var body = view.querySelector('.body'); body.textContent = '';
        var el = document.createElement(kind(file) === 'vid' ? 'video' : 'img');
        el.src = url;
        if (el.tagName === 'VIDEO') { el.controls = true; el.autoplay = true; el.playsInline = true; }
        body.appendChild(el); view.classList.add('on');
    }
    function shut() {
        var v = view.querySelector('video'); if (v) { v.pause(); }
        view.classList.remove('on'); view.querySelector('.body').textContent = '';
    }
    view.querySelector('.close').addEventListener('click', shut);
    view.addEventListener('click', function (e) { if (e.target === view) { shut(); } });
    document.addEventListener('keydown', function (e) { if (e.key === 'Escape') { shut(); } });
    function draw() {
        urls.forEach(function (u) { URL.revokeObjectURL(u); }); urls = [];
        chips.textContent = '';
        var grid = document.createElement('div'); grid.className = 'thumbs'; grid.style.marginTop = '8px';
        proof.forEach(function (file, i) {
            var url = URL.createObjectURL(file); urls.push(url);
            var drop = function (e) { e.preventDefault(); e.stopPropagation(); proof.splice(i, 1); draw(); };
            if (kind(file) === 'aud') {
                var a = document.createElement('div'); a.className = 'aud'; a.style.marginTop = '8px';
                var au = document.createElement('audio'); au.controls = true; au.src = url;
                var bx = document.createElement('button'); bx.type = 'button'; bx.textContent = '✕';
                bx.setAttribute('aria-label', 'Remove ' + file.name); bx.addEventListener('click', drop);
                a.appendChild(au); a.appendChild(bx); chips.appendChild(a); return;
            }
            var t = document.createElement('div'); t.className = 'thumb'; t.title = file.name + ' · ' + size(file.size);
            var m = document.createElement(kind(file) === 'vid' ? 'video' : 'img');
            if (m.tagName === 'VIDEO') { m.src = url + '#t=0.1'; m.muted = true; m.preload = 'metadata'; m.playsInline = true; }
            else { m.src = url; m.alt = file.name; }
            t.appendChild(m);
            if (m.tagName === 'VIDEO') { var pl = document.createElement('span'); pl.className = 'play'; pl.textContent = '▶'; t.appendChild(pl); }
            var x = document.createElement('button'); x.type = 'button'; x.className = 'x'; x.textContent = '✕';
            x.setAttribute('aria-label', 'Remove ' + file.name); x.addEventListener('click', drop);
            t.appendChild(x);
            t.addEventListener('click', function () { open(file, url); });
            grid.appendChild(t);
        });
        if (grid.childNodes.length) { chips.insertBefore(grid, chips.firstChild); }
    }
    pick.addEventListener('change', function () {
        say(''); Array.prototype.forEach.call(pick.files || [], add); pick.value = ''; draw();
    });
    var rec = null, chunks = [], started = 0;
    if (!(window.MediaRecorder && navigator.mediaDevices && navigator.mediaDevices.getUserMedia)) { mic.style.display = 'none'; }
    mic.addEventListener('click', function () {
        if (rec && rec.state === 'recording') { rec.stop(); return; }
        say('');
        navigator.mediaDevices.getUserMedia({ audio: true }).then(function (stream) {
            chunks = []; started = Date.now(); rec = new MediaRecorder(stream);
            rec.ondataavailable = function (e) { if (e.data && e.data.size) { chunks.push(e.data); } };
            rec.onstop = function () {
                stream.getTracks().forEach(function (t) { t.stop(); });
                mic.textContent = '🎤 Voice note';
                var type = rec.mimeType || 'audio/webm', secs = Math.round((Date.now() - started) / 1000);
                var ext = type.indexOf('mp4') > -1 ? 'm4a' : (type.indexOf('ogg') > -1 ? 'ogg' : 'webm');
                add(new File(chunks, 'Voice note ' + (proof.length + 1) + ' (' + secs + 's).' + ext, { type: type.split(';')[0] }));
                draw();
            };
            rec.start(); mic.textContent = '⏹ Stop recording';
        }).catch(function () { say('The microphone could not be opened. Allow it, or attach a recording with 📷.'); });
    });
    f.addEventListener('submit', function (e) {
        var fb = f.querySelector('[name=feedback]');
        if ((by === 'reject' || by === 'clarify') && fb.value.trim().length < 3) {
            e.preventDefault(); document.getElementById('so-need').style.display = 'block'; fb.focus(); return;
        }
        if (rec && rec.state === 'recording') { e.preventDefault(); say('Stop the recording first (⏹).'); return; }
        if (by === 'approve' && window.soSign) {
            var who = document.getElementById('so-signer') || document.getElementById('so-name');
            if (who && !who.value.trim()) { e.preventDefault(); who.focus(); return; }
            if (window.soSign.empty()) {
                e.preventDefault(); window.soSign.need(); return;
            }
            document.getElementById('sg-data').value = window.soSign.png();
        }
        var dt = new DataTransfer();
        if (by === 'reject') { proof.forEach(function (x) { dt.items.add(x); }); }
        hidden.files = dt.files;
        f.querySelectorAll('button[name=action]').forEach(function (b) { b.disabled = true; });
        var a = document.createElement('input'); a.type = 'hidden'; a.name = 'action'; a.value = by || '';
        f.appendChild(a);
    });
})();
